import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// --- 复用组件定义 ---

// 1. 技能详细结构 (保留兼容性补丁)
const skillInfoSchema = z.record(
  z.string().describe('技能名'),
  z.object({
    type: z.enum(['主动', '被动']).describe('类型').prefault('主动'),
    tag: z.enum(['攻击', '治疗', '增益', '减益', '控制', '其他']).describe('标签').prefault('攻击'),
    val: z.string().describe('效果详情 (必须精确, 如: "DMG -15%", "Heal 20% Max HP")').prefault('N/A')
  })
).or(z.array(z.any()).transform(() => ({}))).prefault({});

// 2. 特质详细结构 (保留兼容性补丁)
const traitInfoSchema = z.record(
  z.string().describe('特质名'),
  z.object({
    desc: z.string().describe('具体效果(如: +20%压力)').prefault('Unknown Effect')
  })
).or(z.array(z.any()).transform(() => ({}))).prefault({});

// 3. 饰品详细结构 (保留兼容性补丁)
const trinketInfoSchema = z.record(
  z.string().describe('饰品名'),
  z.object({
    desc: z.string().describe('装备效果').prefault('Unknown Effect')
  })
).or(z.array(z.any()).transform(() => ({}))).prefault({});

// 4. 战斗属性 (移除 catch，让错误暴露出来)
const statsSchema = z.object({
  atk: z.coerce.number().describe('攻击'),
  def: z.coerce.number().describe('防御%'),
  hit: z.coerce.number().describe('命中%'),
  crit: z.coerce.number().describe('暴击%'),
  prec: z.coerce.number().describe('精准'),
  spd: z.coerce.number().describe('速度'),
  dodge: z.coerce.number().describe('闪避%')
}).catchall(z.any()).prefault({});

// 5. 装备
const equipmentSchema = z.object({
  weapon: z.coerce.number().prefault(1),
  armor: z.coerce.number().prefault(1),
  trinkets: trinketInfoSchema
}).prefault({});

// 6. 外观
const appearanceSchema = z.object({
  outfit: z.string().describe('当前服装').prefault('Default Gear'),
  body: z.string().describe('身材特征').prefault('Average'),
  pose: z.string().describe('当前姿势').prefault('Standing')
}).prefault({});

// 7. 设施详细结构
// 兼容逻辑：如果原本是字符串(如"unbuilt")，自动转换为 { level: 0, desc: "unbuilt" }
const facilityDetailSchema = z.object({
  level: z.coerce.number().catch(1).prefault(1),
  desc: z.string().describe('当前外观/运营状态').prefault('正常运营')
}).or(z.string().transform(str => ({ level: 0, desc: str })));

// --- 主 Schema ---
export const schema = z.object({
  world: z.object({
    week: z.coerce.number().prefault(1),
    status: z.string().prefault('平静'),
    exploration: z.record(
      z.enum(['weald', 'warrens', 'cove', 'ruins', 'courtyard', 'farmstead', 'darkest_dungeon']),
      z.coerce.number().min(0).max(100).transform(v => _.clamp(v, 0, 100)) // 探索度如果出错应该报错
    ).prefault({})
  }).prefault({}),

  resource: z.object({
    // 移除 catch，金币出错必须报警
    gold: z.coerce.number().min(0).prefault(0),
    shards: z.coerce.number().min(0).prefault(0)
  }).prefault({}),

// 【核心修改】设施现在是完全开放的结构，且兼容旧数据的字符串格式
  facility: z.record(
    z.string().describe('设施名称'), 
    facilityDetailSchema
  ).prefault({}),

  heir: z.object({
    name: z.string(),
    title: z.string(),
    location: z.string(),
    mission: z.string(),
    class: z.string().describe('职业').prefault('Heir'),
    level: z.coerce.number().prefault(1),
    stats: statsSchema,
    hp: z.object({ 
        current: z.coerce.number(), // HP出错必须报警
        max: z.coerce.number() 
    }).prefault({}),
    stress: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
    mental_state: z.string().prefault('Normal'),
    conditions: z.array(z.string()).prefault([]),
    skills: skillInfoSchema,
    traits: traitInfoSchema,
    equipment: equipmentSchema,
    appearance: appearanceSchema
  }).prefault({}),

  roster: z.record(z.string().describe('女英雄姓名 (仅限女性)'), z.object({
    class: z.string().describe('职业').prefault('Adventurer'),
    race: z.string().describe('种族').prefault('Human'),
    level: z.coerce.number().describe('等级').prefault(0),

    stats: statsSchema,
    hp: z.object({ 
        current: z.coerce.number(), 
        max: z.coerce.number() 
    }).prefault({}),
    stress: z.coerce.number().transform(v => _.clamp(v, 0, 200)).prefault(0),
    mental_state: z.string().prefault('Normal'),
    conditions: z.array(z.string()).describe('负面状态').prefault([]),

    skills: skillInfoSchema,
    traits: traitInfoSchema,
    equipment: equipmentSchema,

    appearance: appearanceSchema,
    narrative: z.object({
      thought: z.string().describe('内心想法').prefault('...'),
      action: z.string().describe('当前行为').prefault('Idle')
    }).prefault({}),

    affection: z.coerce.number().transform(v => _.clamp(v, 0, 10)).prefault(0),
    relationship: z.string().prefault('Stranger')
  })).prefault({}),

  inventory: z.object({
    // 【保留】这里必须保留 catch(0)，因为 AI 移除物品时会导致字段消失/undefined，需要自动归零
    consumables: z.record(
        z.enum(['food', 'torch', 'blood', 'invitation']), 
        z.coerce.number().min(0).catch(0)
    ).prefault({}),

    trophies: z.record(z.string(), z.object({
      desc: z.string(),
      effect: z.string()
    })).prefault({}),

    // 【保留】同上
    gifts: z.record(
        z.enum(['flower', 'necklace', 'ring']), 
        z.coerce.number().min(0).catch(0)
    ).prefault({})
  }).prefault({}),

  expedition: z.object({
    state: z.enum(['征战', '休息']).prefault('休息'),
    location: z.string().prefault('None'),
    team: z.record(z.string(), z.string()).prefault({}),
    goal: z.string().prefault('None'),
    supplies: z.record(z.string(), z.coerce.number().catch(0)).prefault({}),
    farmstead_light: z.string().prefault('Default')
  }).prefault({})
});

$(() => {
  registerMvuSchema(schema);
})
